var DATA = {"source": "Structured JSON logs", "steps": "Parse logs|Order by timestamp|Rebuild call tree|Verify against metrics", "fidelity": "High (95% of calls)", "fragments": "t=1:enter:handle|t=2:enter:auth|t=3:exit:auth|t=4:exit:handle"};
console.log("Trace source: " + DATA.source + " | Fidelity: " + DATA.fidelity);
var frags = DATA.fragments.split("|").map(function (s) { return s.trim(); });
// reconstruct call order: fragments look like "t=3:enter:foo" / "t=7:exit:foo"
var events = frags.map(function (fr) {
  var p = fr.split(":");
  return { t: parseInt(p[0].replace("t=", ""), 10) || 0, kind: p[1], fn: p[2] };
}).sort(function (a, b) { return a.t - b.t; });
console.log("--- reconstructed timeline ---");
var stack = [];
events.forEach(function (e) {
  if (e.kind === "enter") { stack.push(e.fn); console.log("  t=" + e.t + " enter " + e.fn + "  (depth " + stack.length + ")"); }
  else if (e.kind === "exit") { var f = stack.pop(); console.log("  t=" + e.t + " exit " + e.fn + (f === e.fn ? "" : "  <-- MISMATCH, expected " + f)); }
  else console.log("  t=" + e.t + " " + e.kind + " " + e.fn);
});
console.log("--- reconstruction steps ---");
DATA.steps.split("|").forEach(function (s, i) { console.log("  " + (i + 1) + ". " + s.trim()); });
console.log("RESULT: " + events.length + " events ordered; max depth " + Math.max.apply(null, [0].concat(events.map(function (e, i) { return i; }))) + " processed.");

